168:     protected bool GetOptionParts(string argument, out string flag, out string name, out string sep, out string value)
169:     {
170:         if (argument == null)
171:             throw new ArgumentNullException(nameof(argument));
172: 
173:         flag = name = sep = value = null;
174:         var m       = _valueOption.Match(argument);
175:         if (!m.Success)
176:             return false;
177:         flag = m.Groups["flag"].Value;
178:         name = m.Groups["name"].Value;
179: 
180:         if (m.Groups["sep"].Success && m.Groups["value"].Success)
181:         {
182:             sep   = m.Groups["sep"].Value;
183:             value = m.Groups["value"].Value;
184:         }
185: 
186:         return true;
187:     }
