189:     protected virtual bool Parse(string argument, OptionContext c)
190:     {
191:         if (c.Option != null)
192:         {
193:             ParseValue(argument, c);
194:             return true;
195:         }
196: 
197:         if (!GetOptionParts(argument, out var f, out var n, out var s, out var v))
198:             return false;
199: 
200:         if (!Contains(n))
201:             return ParseBool(argument, n, c) || ParseBundledValue(f, string.Concat(n + s + v), c);
202: 
203:         var p = this[n];
204:         c.OptionName = f + n;
205:         c.Option     = p;
206:         switch (p.OptionValueType)
207:         {
208:             case OptionValueType.None:
209:                 c.OptionValues.Add(n);
210:                 c.Option.Invoke(c);
211:                 break;
212:             case OptionValueType.Optional:
213:             case OptionValueType.Required:
214:                 ParseValue(v, c);
215:                 break;
216:             default:
217:                 throw new ArgumentOutOfRangeException();
218:         }
219: 
220:         return true;
221:     }
