223:     private void ParseValue(string option, OptionContext c)
224:     {
225:         if (option != null)
226:             foreach (var o in c.Option.ValueSeparators != null
227:                                   ? option.Split(c.Option.ValueSeparators, StringSplitOptions.None)
228:                                   :
229:                                   [
230:                                       option
231:                                   ])
232:                 c.OptionValues.Add(o);
233:         if (c.OptionValues.Count == c.Option.MaxValueCount || c.Option.OptionValueType == OptionValueType.Optional)
234:             c.Option.Invoke(c);
235:         else if (c.OptionValues.Count > c.Option.MaxValueCount)
236:             throw new OptionException(MessageLocalizer($"Error: Found {c.OptionValues.Count} option values when expecting {c.Option.MaxValueCount}."), c.OptionName);
237:     }
