239:     private bool ParseBool(string option, string n, OptionContext c)
240:     {
241:         string rn;
242:         if (n.Length < 1 || (n[^1] != '+' && n[^1] != '-') || !Contains(rn = n[..^1]))
243:             return false;
244: 
245:         var p = this[rn];
246:         var v = n[^1] == '+' ? option : null;
247:         c.OptionName = option;
248:         c.Option     = p;
249:         c.OptionValues.Add(v);
250:         p.Invoke(c);
