254:     private bool ParseBundledValue(string f, string n, OptionContext c)
255:     {
256:         if (f != "-")
257:             return false;
258:         for (var i = 0; i < n.Length; ++i)
259:         {
260:             var opt = f + n[i];
261:             var rn  = n[i].ToString();
262:             if (!Contains(rn))
263:                 return i == 0 ? false : throw new OptionException(string.Format(MessageLocalizer("Cannot bundle unregistered option '{0}'."), opt), opt);
264: 
265:             var p = this[rn];
266:             switch (p.OptionValueType)
267:             {
268:                 case OptionValueType.None:
269:                     Invoke(c, opt, n, p);
270:                     break;
271:                 case OptionValueType.Optional:
272:                 case OptionValueType.Required:
273:                 {
274:                     var v = n[(i + 1)..];
275:                     c.Option     = p;
276:                     c.OptionName = opt;
277:                     ParseValue(v.Length != 0 ? v : null, c);
278:                     return true;
279:                 }
280: 
281:                 default:
282:                     throw new InvalidOperationException("Unknown OptionValueType: " + p.OptionValueType);
283:             }
284:         }
285: 
286:         return true;
287:     }
