297:     public void WriteOptionDescriptions(TextWriter o)
298:     {
299:         foreach (var p in this)
300:         {
301:             var written = 0;
302:             if (!WriteOptionPrototype(o, p, ref written))
303:                 continue;
304: 
305:             if (written < OptionWidth)
306:             {
307:                 o.Write(new string(' ', OptionWidth - written));
308:             }
309:             else
310:             {
311:                 o.WriteLine();
312:                 o.Write(new string(' ', OptionWidth));
313:             }
314: 
315:             var lines = GetLines(MessageLocalizer(GetDescription(p.Description)));
316:             o.WriteLine(lines[0]);
317:             var prefix = new string(' ', OptionWidth + 2);
318:             for (var i = 1; i < lines.Count; ++i)
319:             {
320:                 o.Write(prefix);
321:                 o.WriteLine(lines[i]);
322:             }
