326:     private bool WriteOptionPrototype(TextWriter o, Option p, ref int written)
327:     {
328:         var names = p.Names;
329: 
330:         var i = GetNextOptionIndex(names, 0);
331:         if (i == names.Length)
332:             return false;
333: 
334:         if (names[i].Length == 1)
335:         {
336:             Write(o, ref written, "  -");
337:             Write(o, ref written, names[0]);
338:         }
339:         else
340:         {
341:             Write(o, ref written, "      --");
342:             Write(o, ref written, names[0]);
343:         }
344: 
345:         for (i = GetNextOptionIndex(names, i + 1); i < names.Length; i = GetNextOptionIndex(names, i + 1))
346:         {
347:             Write(o, ref written, ", ");
348:             Write(o, ref written, names[i].Length == 1 ? "-" : "--");
349:             Write(o, ref written, names[i]);
350:         }
351: 
352:         if (p.OptionValueType is not (OptionValueType.Optional or OptionValueType.Required))
353:             return true;
354: 
355:         if (p.OptionValueType == OptionValueType.Optional)
356:             Write(o, ref written, MessageLocalizer("["));
357: 
358:         Write(o, ref written, MessageLocalizer("=" + GetArgumentName(0, p.MaxValueCount, p.Description)));
359: 
360:         var sep = p.ValueSeparators is { Length: > 0 } ? p.ValueSeparators[0] : " ";
361:         for (var c = 1; c < p.MaxValueCount; ++c)
362:             Write(o, ref written, MessageLocalizer(sep + GetArgumentName(c, p.MaxValueCount, p.Description)));
363: 
364:         if (p.OptionValueType == OptionValueType.Optional)
365:             Write(o, ref written, MessageLocalizer("]"));
366: 
367:         return true;
368:     }
