383:     private static string GetArgumentName(int index, int maxIndex, string description)
384:     {
385:         if (description == null)
386:             return maxIndex == 1 ? "VALUE" : "VALUE" + (index + 1);
387:         var nameStart = maxIndex == 1 ? ["{0:", "{"] : new[]{"{" + index + ":"};
388:         foreach (var t in nameStart)
389:         {
390:             int start, j = 0;
391:             do {
392:                 start = description.IndexOf (t, j, StringComparison.Ordinal);
393:             } while (start >= 0 && j != 0 && description [j++ - 1] == '{');
394:             if (start == -1)
395:                 continue;
396:             var end = description.IndexOf ("}", start, StringComparison.Ordinal);
397:             if (end == -1)
398:                 continue;
399:             return description.Substring (start + t.Length, end - start - t.Length);
400:         }
401:         return maxIndex == 1 ? "VALUE" : "VALUE" + (index + 1);
402:     }
