404:     private static string GetDescription(string description)
405:     {
406:         if (description == null)
407:             return string.Empty;
408: 
409:         var sb    = new StringBuilder(description.Length);
410:         var start = -1;
411:         for (var i = 0; i < description.Length; ++i)
412:             switch (description[i])
413:             {
414:                 case '{':
415:                     if (i == start)
416:                     {
417:                         sb.Append('{');
418:                         start = -1;
419:                     }
420:                     else if (start < 0)
421:                     {
422:                         start = i + 1;
423:                     }
424: 
425:                     break;
426:                 case '}':
427:                     if (start < 0)
428:                     {
429:                         if (i + 1 == description.Length || description[i + 1] != '}')
430:                             throw new InvalidOperationException("Invalid option description: " + description);
431:                         ++i;
432:                         sb.Append('}');
433:                     }
