2: // Project:  NDesk.Options.Core
3: // File:     Options.cs
4: // Author:   Latency McLaughlin
5: // Date:     04/04/2024
6: // ****************************************************************************
7: 
8: //
9: // A Getopt::Long-inspired option parsing library for C#.
10: //
11: // NDesk.Options.OptionSet is built upon a key/value table, where the
12: // key is a option format string and the value is a delegate that is 
13: // invoked when the format string is matched.
14: //
15: // Option format strings:
16: //  Regex-like BNF Grammar: 
17: //    name: .+
18: //    type: [=:]
19: //    sep: ( [^{}]+ | '{' .+ '}' )?
20: //    aliases: ( name type sep ) ( '|' name type sep )*
21: // 
22: // Each '|'-delimited name is an alias for the associated action.  If the
23: // format string ends in a '=', it has a required value.  If the format
24: // string ends in a ':', it has an optional value.  If neither '=' or ':'
25: // is present, no value is supported.  `=' or `:' need only be defined on one
26: // alias, but if they are provided on more than one they must be consistent.
27: //
28: // Each alias portion may also end with a "key/value separator", which is used
29: // to split option values if the option accepts > 1 value.  If not specified,
30: // it defaults to '=' and ':'.  If specified, it can be any character except
31: // '{' and '}' OR the *string* between '{' and '}'.  If no separator should be
32: // used (i.e. the separate values should be distinct arguments), then "{}"
33: // should be used as the separator.
34: //
35: // Options are extracted either from the current option by looking for
36: // the option name followed by an '=' or ':', or is taken from the
37: // following option IFF:
38: //  - The current option does not contain a '=' or a ':'
39: //  - The current option requires a value (i.e. not a Option type of ':')
40: //
41: // The `name' used in the option format string does NOT include any leading
42: // option indicator, such as '-', '--', or '/'.  All three of these are
43: // permitted/required on any named option.
44: //
45: // Option bundling is permitted so long as:
46: //   - '-' is used to start the option group
47: //   - all of the bundled options are a single character
48: //   - at most one of the bundled options accepts a value, and the value
49: //     provided starts from the next character to the end of the string.
50: //
51: // This allows specifying '-a -b -c' as '-abc', and specifying '-D name=value'
52: // as '-Dname=value'.
53: //
54: // Option processing is disabled by specifying "--".  All options after "--"
55: // are returned by OptionSet.Parse() unchanged and unprocessed.
56: //
57: // Unprocessed options are returned from OptionSet.Parse().
58: //
59: // Examples:
60: //  int verbose = 0;
61: //  OptionSet p = new OptionSet ()
62: //    .Add ("v", v => ++verbose)
63: //    .Add ("name=|value=", v => Console.WriteLine (v));
64: //  p.Parse (new string[]{"-v", "--v", "/v", "-name=A", "/name", "B", "extra"});
65: //
66: // The above would parse the argument string array, and would invoke the
67: // lambda expression three times, setting `verbose' to 3 when complete.  
68: // It would also print out "A" and "B" to standard output.
69: // The returned array would contain the string "extra".
70: //
71: // C# 3.0 collection initializers are supported and encouraged:
72: //  var p = new OptionSet () {
73: //    { "h|?|help", v => ShowHelp () },
74: //  };
75: //
76: // System.ComponentModel.TypeConverter is also supported, allowing the use of
77: // custom data types in the callback type; TypeConverter.ConvertFromString()
78: // is used to convert the value option to an instance of the specified
79: // type:
80: //
81: //  var p = new OptionSet () {
82: //    { "foo=", (Foo f) => Console.WriteLine (f.ToString ()) },
83: //  };
84: //
85: // Random other tidbits:
86: //  - Boolean options (those w/o '=' or ':' in the option format string)
87: //    are explicitly enabled if they are followed with '+', and explicitly
88: //    disabled if they are followed with '-':
89: //      string a = null;
90: //      var p = new OptionSet () {
91: //        { "a", s => a = s },
92: //      };
93: //      p.Parse (new string[]{"-a"});   // sets v != null
94: //      p.Parse (new string[]{"-a+"});  // sets v != null
95: //      p.Parse (new string[]{"-a-"});  // sets v == null
96: //
97: 
