99: 
100: namespace NDesk.Options;
101: 
102: public class OptionValueCollection : IList, IList<string>
103: {
104:     private readonly OptionContext _c;
105:     private readonly List<string>  _values = [];
106: 
107:     internal OptionValueCollection(OptionContext c) => _c = c;
108: 
109:     IEnumerator IEnumerable.GetEnumerator() => _values.GetEnumerator();
110: 
111:     void ICollection.CopyTo(Array array, int index) => (_values as ICollection).CopyTo(array, index);
112: 
