121:     bool IList.Contains(object value) => (_values as IList).Contains(value);
122:     int IList. IndexOf(object  value) => (_values as IList).IndexOf(value);
123: 
124:     void IList.Insert(int index, object value) => (_values as IList).Insert(index, value);
125: 
126:     void IList.Remove(object value) => (_values as IList).Remove(value);
127: 
128:     void IList.RemoveAt(int index) => (_values as IList).RemoveAt(index);
129: 
