133:     {
134:         get => this[index];
135:         set => (_values as IList)[index] = value;
136:     }
137:     public IEnumerator<string> GetEnumerator() => _values.GetEnumerator();
138:     public void Add(string item) => _values.Add(item);
139: 
140:     public bool Contains(string item) => _values.Contains(item);
141: 
142:     public void CopyTo(string[] array, int arrayIndex) => _values.CopyTo(array, arrayIndex);
143: 
144:     public bool Remove(string item) => _values.Remove(item);
145: 
146:     public int IndexOf(string item) => _values.IndexOf(item);
147: 
148:     public void Insert(int index, string item) => _values.Insert(index, item);
149: 
150:     public void RemoveAt(int index) => _values.RemoveAt(index);
151: 
152:     public string this[int index]
153:     {
154:         get
155:         {
156:             AssertValid(index);
157:             return index >= _values.Count ? null : _values[index];
158:         }
159:         set => _values[index] = value;
160:     }
161: 
162:     public List<string> ToList() => [.._values];
163: 
164:     public string[] ToArray() => [.. _values];
165: 
166:     public override string ToString() => string.Join(", ", (string[]) [.. _values]);
167: 
168:     private void AssertValid(int index)
169:     {
170:         if (_c.Option == null)
171:             throw new InvalidOperationException("OptionContext.Option is null.");
172:         if (index >= _c.Option.MaxValueCount)
173:             throw new ArgumentOutOfRangeException(nameof(index));
174:         if (_c.Option.OptionValueType == OptionValueType.Required && index >= _values.Count)
175:             throw new OptionException(string.Format(_c.OptionSet.MessageLocalizer("Missing required value for option '{0}'."), _c.OptionName), _c.OptionName);
176:     }
